/**
 * CIDR reference table: what a prefix length actually means, for every
 * IPv4 prefix, the IPv6 prefixes that come up in practice, and the address
 * ranges that are reserved rather than routable.
 *
 * `subnet` and `subnet-planlayici` compute an answer for the address someone
 * types in; this tool has no input at all — it is the table somebody scans
 * with their eyes, or searches by typing the one fragment they remember
 * (a mask, a wildcard, a hex value, a well-known block). That is why the
 * IPv4 half is generated by a loop rather than typed out 33 times: a prefix
 * length determines its mask, its wildcard, its hex form and its address
 * count by a fixed formula, and retyping a formula's output by hand is
 * exactly how a `/24` row ends up with a `/23` mask nobody notices until
 * somebody's ACL breaks. Only the sentence explaining what a block *of that
 * size* is actually used for is hand-written, because a formula cannot know
 * that a `/29` is what an ISP hands out behind a firewall.
 *
 * The worked example in every IPv4 row's `example` field is the same base
 * address, 203.0.113.45, masked down for that row — one of RFC 5737's
 * documentation addresses (see the `ayrilmis` section below), chosen so the
 * examples are consistent with each other and never look like a real
 * assignment. The IPv6 rows are hand-picked rather than generated, because
 * unlike IPv4's uniform 0–32 there is no complete list of prefixes anyone
 * looks up — only the handful that mean something (`/64` for SLAAC, `/48`
 * for a site) — but every address count is still computed from the prefix
 * with `BigInt`, never typed, because an IPv6 block's size stops fitting in
 * a normal number well before `/64`.
 */
import type { ReferenceRow, ReferenceSection } from "./reference";

export const subnetCedveliSections: ReferenceSection[] = [
  {
    id: "ipv4",
    label: "IPv4 prefiksləri",
    hint: "/32-dən /0-a qədər bütün 33 prefiks: maska, wildcard və nə üçün işlədildiyi.",
  },
  {
    id: "ipv6",
    label: "IPv6 prefiksləri",
    hint: "IPv6-da yayım (broadcast) ünvanı yoxdur, ona görə burada 'istifadə oluna bilən host' IPv4-dəki kimi cəmi-2 düsturu ilə hesablanmır, bloku bütöv əhatə edən ünvan sayı göstərilir.",
  },
  { id: "ayrilmis", label: "Ayrılmış və xüsusi diapazonlar" },
];

/* ---------- IPv4: generated, not typed ---------- */

function maskFromPrefix(prefix: number): number {
  if (prefix <= 0) return 0;
  if (prefix >= 32) return 0xffffffff;
  return (0xffffffff << (32 - prefix)) >>> 0;
}

function formatIpv4(value: number): string {
  const unsigned = value >>> 0;
  return [
    (unsigned >>> 24) & 0xff,
    (unsigned >>> 16) & 0xff,
    (unsigned >>> 8) & 0xff,
    unsigned & 0xff,
  ].join(".");
}

function toHexMask(value: number): string {
  return (value >>> 0).toString(16).padStart(8, "0");
}

/** Thousands-grouped digits with a thin space, same convention the subnet
 *  calculator uses for the same reason: a bare `4294967296` is not a number
 *  anyone can read at a glance. */
function formatCount(value: number): string {
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

/** RFC 5737 TEST-NET-3 — reserved exactly for use in examples like this one. */
const DEMO_ADDRESS = (((203 << 24) | (0 << 16) | (113 << 8) | 45) >>> 0) as number;

