/** Extra search words beyond the wildcard and the hex mask — a synonym, an
 *  old classful name, a spec name — for the handful of prefixes visitors
 *  reach for by something other than the number. */
const IPV4_EXTRA_MATCH: Partial<Record<number, string[]>> = {
  0: ["default route", "default marsrut"],
  8: ["class a", "a sinfi"],
  16: ["class b", "b sinfi"],
  24: ["class c", "c sinfi"],
  31: ["point-to-point", "rfc 3021"],
  32: ["host route", "tek host"],
};

function countClause(prefix: number, total: string, usable: string): string {
  if (prefix === 32) {
    return `Bu blok tək bir ünvandır (${total}) və elə özü də host üçün istifadə olunur (${usable}): şəbəkə və yayım ayrımı mənasızdır, ona görə host sayı sıfır deyil, birdir`;
  }
  if (prefix === 31) {
    return `Bu blokda ${total} ünvan var və hər ikisi (${usable}) host üçün istifadə olunur, sıfır yox: RFC 3021 bu ölçünü xüsusi olaraq nöqtə-nöqtə əlaqə üçün ayırıb, şəbəkə/yayım konvensiyası tətbiq olunmur`;
  }
  return `Bu blokda ${total} ünvan var, bunlardan ${usable} host üçün istifadə oluna bilər (şəbəkə və yayım ünvanları çıxılıb)`;
}

function buildIpv4Rows(): ReferenceRow[] {
  const rows: ReferenceRow[] = [];
  for (let prefix = 32; prefix >= 0; prefix--) {
    const mask = maskFromPrefix(prefix);
    const wildcard = ~mask >>> 0;
    const total = 2 ** (32 - prefix);
    const usable = prefix === 32 ? 1 : prefix === 31 ? 2 : total - 2;
    const network = (DEMO_ADDRESS & mask) >>> 0;

    rows.push({
      term: `/${prefix}`,
      label: formatIpv4(mask),
      note: `${countClause(prefix, formatCount(total), formatCount(usable))}. ${IPV4_USAGE[prefix]}`,
      section: "ipv4",
      example: `${formatIpv4(network)}/${prefix}`,
      match: [formatIpv4(wildcard), toHexMask(mask), ...(IPV4_EXTRA_MATCH[prefix] ?? [])],
    });
  }
  return rows;
}

/* ---------- IPv6: hand-picked, still computed ---------- */

const SUPERSCRIPT_DIGITS: Record<string, string> = {
  "0": "⁰",
  "1": "¹",
  "2": "²",
  "3": "³",
  "4": "⁴",
  "5": "⁵",
  "6": "⁶",
  "7": "⁷",
  "8": "⁸",
  "9": "⁹",
};

function toSuperscript(value: number): string {
  return String(value)
    .split("")
    .map((digit) => SUPERSCRIPT_DIGITS[digit] ?? digit)
    .join("");
}

function formatBigCount(value: bigint): string {
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, " ");
}

