function buildIpv6Rows(): ReferenceRow[] {
  return IPV6_SPECS.map(({ prefix, usage, example, match }) => {
    const exponent = 128 - prefix;
    const count = 2n ** BigInt(exponent);
    return {
      term: `/${prefix}`,
      label: `2${toSuperscript(exponent)} ünvan`,
      note: `${formatBigCount(count)} ünvandan ibarətdir: ${usage}`,
      section: "ipv6",
      example,
      match,
    };
  });
}

